solution.code:
#include <stdio.h>
#include <string.h>

struct Book {
    char title[30];
    int pages;
};

int main() {
    struct Book b;
    strcpy(b.title, "C Primer");
    b.pages = 420;
    printf("%s has %d pages\n", b.title, b.pages);
    return 0;
}
